namespace detail {

template <int V>
struct MolangVersion_;

template <int V> requires (V < 827)
struct MolangVersion_<V> { using type = base::MolangVersion; };

template <int V> requires (V >= 827)
struct MolangVersion_<V> { using type = v827::MolangVersion; };

template <int V>
struct ExpressionOp_;

template <int V> requires (V < 800)
struct ExpressionOp_<V> { using type = base::ExpressionOp; };

template <int V> requires (V >= 800 && V < 859)
struct ExpressionOp_<V> { using type = v800::ExpressionOp; };

template <int V> requires (V >= 859)
struct ExpressionOp_<V> { using type = v859::ExpressionOp; };

}  // namespace detail

template <int V> using MolangVersion_ = typename detail::MolangVersion_<V>::type;
template <int V> using ExpressionOp_ = typename detail::ExpressionOp_<V>::type;

